def solve(payload):
    seen = set()
    violations = []
    previous_id = payload["initial_previous_id"]
    previous_time = None
    for index, record in enumerate(payload["records"]):
        issues = []
        if record["sequence"] != payload["start_sequence"]+index:
            issues.append("sequence")
        if record["previous_id"] != previous_id:
            issues.append("previous_id")
        if record["id"] in seen:
            issues.append("duplicate_id")
        if previous_time is not None and record["time_s"] < previous_time:
            issues.append("time_regression")
        if issues:
            violations.append({"index": index, "issues": issues})
        seen.add(record["id"])
        previous_id = record["id"]
        previous_time = record["time_s"]
    return {"valid": not violations, "violations": violations}

